            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 70
          },
          "phases": [
            {
              "localId": "phase_1",
              "title": "Ohm's law in one simple series circuit",
              "outcome": "Solve and explain one changed simple series circuit independently using V=IR and series rules.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
