            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Directly supplies the accepted outcome: explaining and using Ohm's law in one simple series circuit, including series current equality and voltage drops."
          }
        ],
