            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has not been shown to have prior electricity instruction; the integrated task therefore introduces voltage, current, resistance and series rules rather than assuming them.",
            "No assessment date, weight or syllabus is supplied, so effort is estimated from the bounded outcome rather than from exam importance."
          ],
          "tradeOffs": [
            "Only one committed activity is booked. Additional practice, timed drills or a second changed circuit are not committed because the integrated task already provides explanation, supported application and an independent changed example; adding them would extend the assignment without a distinct evidence contribution.",
