{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "A single working Python script that reads a small expenses CSV, uses a loop and a dictionary to total spending by category, and prints the totals — demonstrating the shared loops/dictionaries prerequisite that both the CSV and JSON reports depend on."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare both a CSV report and a JSON report. I am new to Python loops and dictionaries. A shared loops/dictionary prerequisite should have one owner and count once.",
          "explanation": "The learner is new to loops and dictionaries, and both the CSV and JSON report goals depend on that same prerequisite. Rather than duplicate prerequisite work in both Plans, plan_1 owns the shared loops/dictionaries learning as a single committed activity. The next useful checkpoint is a small working script that reads a tiny CSV and totals spending by category using a loop and a dictionary; this proves the prerequisite before any report formatting is attempted. The CSV totals report itself remains strategic and unbooked until that checkpoint is independently demonstrated.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 60,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "prereq",
              "title": "Shared loops and dictionaries prerequisite",
              "outcome": "Use a loop and a dictionary to accumulate totals from a small CSV and print the result.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "The learner runs a script that reads a small expenses CSV, loops over its rows, accumulates per-category totals in a dictionary, and prints correct totals without assistance."
            },
            {
              "localId": "csv_report",
              "title": "CSV totals report",
              "outcome": "Produce a CSV report of totals by category from a larger expenses file.",
              "readinessCriterion": "A CSV report file is produced with correct per-category totals and can be explained line by line."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Owns the shared loops/dictionaries prerequisite: the committed activity teaches loop iteration over CSV rows and dictionary accumulation of per-category totals, which plan_2 depends on via a shared edge."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The CSV totals report is the eventual plan_1 deliverable; it stays strategic and unbooked until the shared prerequisite checkpoint is independently demonstrated."
          }
        ],
        "activities": [
          {
            "localId": "loops_dict_prereq",
            "outcomeRefs": [
              "prereq"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Learn loops and dictionaries by totalling a small CSV",
            "activityType": "Guided coding practice",
            "purpose": "Establish the shared loops/dictionaries prerequisite that both the CSV and JSON reports depend on, using a small concrete data set.",
            "instructions": "Create a file named expenses.csv with these exact rows:\ncategory,amount\nfood,12.50\ntransport,3.00\nfood,7.25\nrent,500.00\ntransport,2.75\n\nWrite a Python script that:\n1. Opens expenses.csv and reads it line by line.\n2. Skips the header line.\n3. For each remaining line, splits it on the comma into a category and an amount.\n4. Uses a dictionary to accumulate the total amount per category.\n5. After the loop, prints each category and its total.\n\nRun the script and check that the output is:\nfood 19.75\ntransport 5.75\nrent 500.00\n\nIf a total is wrong, find the line in your loop or dictionary update that caused it and fix it. Then change one amount in the CSV, run the script again, and confirm the printed total changes correctly. Do not use pandas or any external library; use only plain Python loops and dictionaries.",
            "completionCriterion": "The script runs without errors, prints the three correct category totals for the supplied CSV, and prints updated correct totals after one amount in the CSV is changed.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has Python installed and can run a script from the command line or an editor.",
            "The learner has not yet used loops or dictionaries in Python."
          ],
          "tradeOffs": [
            "The CSV totals report is not booked yet; the first checkpoint is the shared prerequisite, so the report is deferred until the prerequisite is demonstrated."
          ],
          "unresolvedUncertainty": [
            "How quickly the learner becomes comfortable with dictionary accumulation is unknown; the effort range reflects this."
          ],
          "stoppingConditions": [
            "Stop after the script correctly totals the supplied CSV and correctly reflects one changed amount."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report with the same loops/dictionary prerequisite as the CSV target. Do not duplicate prerequisite work; use its owning Plan.",
          "explanation": "The JSON expenses report depends on the same loops/dictionaries prerequisite owned by plan_1. No prerequisite activity is booked here; instead a shared HARD dependency points to plan_1's committed prerequisite activity. The JSON report itself remains strategic and unbooked until that prerequisite checkpoint is independently demonstrated.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 75
          },
          "phases": [
            {
              "localId": "json_report",
              "title": "JSON expenses report",
              "outcome": "Produce a JSON report of totals by category from an expenses file.",
              "readinessCriterion": "A JSON file is produced with correct per-category totals and can be explained line by line."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The shared loops/dictionaries prerequisite is owned by plan_1; plan_2 relies on it through a shared HARD dependency rather than duplicating the work."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report is the eventual plan_2 deliverable; it stays strategic and unbooked until the shared prerequisite checkpoint is independently demonstrated."
          }
        ],
        "activities": [],
        "decisions": {
          "assumptions": [
            "The learner will complete the shared loops/dictionaries prerequisite in plan_1 before starting the JSON report."
          ],
          "tradeOffs": [
            "No JSON report activity is booked yet; booking it before the shared prerequisite is demonstrated would duplicate or front-run prerequisite work."
          ],
          "unresolvedUncertainty": [
            "The exact JSON structure the learner wants is not yet specified; this can be decided once the prerequisite is demonstrated."
          ],
          "stoppingConditions": [
            "No stopping condition yet; the JSON report is not booked."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "loops_dict_prereq"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "json_report"
      },
      "strength": "HARD",
      "reason": "The JSON expenses report requires the same loops/dictionaries capability taught in plan_1's committed prerequisite activity; plan_2 must not duplicate that work."
    }
  ],
  "tradeOffExplanation": "The shared loops/dictionaries prerequisite is owned once by plan_1 and booked as a single committed activity, so plan_2 books no prerequisite work and instead depends on it. The CSV and JSON report deliverables remain strategic and unbooked until the prerequisite checkpoint is independently demonstrated, keeping the first step small and avoiding duplicated prerequisite work."
}

