{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You correctly choose and justify a method for each of five changed circuits and solve them without assistance; any circuit you miss is reworked with the rule explained and re-checked on a fresh changed circuit."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "I say I have mastered circuit methods, but in my self-reported last check I got four of five changed circuits wrong. Do not ignore this contradiction or certify mastery from my claim; choose proportionate education and a meaningful check.",
          "explanation": "The self-report of mastery is contradicted by the reported 4/5 failure on changed circuits, so mastery is not credited. The observed failure pattern (wrong on changed circuits) points to weak method selection and transfer rather than total absence of knowledge, so the plan starts with a compact diagnostic set of changed circuits to locate which methods and topologies fail, then teaches the specific selection rules those failures reveal, then requires an independent changed-circuit check. No preparatory lessons are booked before the diagnostic because the failure itself is the evidence of what to teach; remediation is contingent on the diagnostic result. The final check is the meaningful stopping point: correct method choice, valid reason, and correct solution on changed work without assistance.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "diagnose",
              "title": "Locate the method-selection failures",
              "outcome": "A record of which circuit methods and topologies you chose wrongly and why, from five changed circuits.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "You have attempted all five circuits, recorded your chosen method and reason for each, and marked which were wrong."
            },
            {
              "localId": "repair",
              "title": "Teach the selection rules the diagnostic exposed",
              "outcome": "Correct selection rules for the specific methods and topologies you got wrong, applied to fresh changed circuits.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "You can state the selection rule for each failed method and apply it correctly to a fresh changed circuit."
            },
            {
              "localId": "verify",
              "title": "Independent changed-circuit check",
              "outcome": "Five changed circuits solved with correct method choice, valid reason, and correct solution without assistance.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 90
              },
              "readinessCriterion": "All five circuits are correct with a valid selection reason for each, with no assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The whole plan targets independent circuit method selection: diagnosing which selections fail, teaching the specific selection rules, and verifying correct selection and solution on changed circuits."
          }
        ],
        "activities": [
          {
            "localId": "diagnostic_set",
            "outcomeRefs": [
              "diagnose"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Diagnostic: five changed circuits",
            "activityType": "Diagnostic problem set",
            "purpose": "Locate exactly which circuit methods and topologies you select wrongly, so teaching targets the real gaps rather than assumed ones.",
            "instructions": "Solve these five changed circuits. For each, write the method you chose, one sentence on why that method fits the circuit's topology and source type, and your solution. Do not look up methods while working; mark any circuit you are unsure about. Circuits: (1) Two resistors in series with a 12 V source, find the current. (2) Two resistors in parallel across a 12 V source, find the total current. (3) A series-parallel network with a 9 V source and three resistors, find the voltage across the middle resistor. (4) A circuit with a 6 V source and two resistors in series, find the power in each resistor. (5) A circuit with a 10 V source, a 4 ohm and a 6 ohm resistor in series, find the voltage across the 6 ohm resistor. Record your chosen method and reason for each before checking any answer.",
            "completionCriterion": "All five circuits attempted with a recorded method, a one-sentence selection reason, and a solution; wrong items and unsure items clearly marked.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "targeted_teaching",
            "outcomeRefs": [
              "repair"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Teach the selection rules your diagnostic exposed",
            "activityType": "Guided rule explanation and application",
            "purpose": "Explain and apply the specific method-selection rules for the circuits you got wrong, so the rule is understood rather than memorized.",
            "instructions": "For each circuit you got wrong or marked unsure in the diagnostic, work through it here. First write the selection rule in your own words: what feature of the circuit (series, parallel, series-parallel, source value, what is asked) tells you which method to use. Then re-solve that circuit step by step, explaining each step. Then solve one fresh changed circuit of the same type that you create yourself, and check it. If you got all five diagnostic circuits right, instead pick the two you found hardest and write the selection rule and a fresh changed example for each. Do not use a method you have not been taught; if a circuit seems to need one, say so and explain why the taught methods do not fit.",
            "completionCriterion": "For every failed or unsure diagnostic circuit, a written selection rule, a correct step-by-step re-solution, and a correct fresh changed example you created and checked.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "diagnostic_set"
            ]
          },
          {
            "localId": "independent_check",
            "outcomeRefs": [
              "verify"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Independent changed-circuit check",
            "activityType": "Unaided assessment",
            "purpose": "Verify that you can choose and justify a method and solve changed circuits without assistance, which is the accepted mastery outcome.",
            "instructions": "Solve these five changed circuits without assistance, notes, or lookups. For each, write the method you chose, one sentence on why it fits, and your solution. Circuits: (1) A 24 V source with a 3 ohm and a 5 ohm resistor in series, find the current. (2) A 12 V source with a 2 ohm and a 6 ohm resistor in parallel, find the current through the 6 ohm resistor. (3) A series-parallel network with a 15 V source, a 4 ohm resistor in series with a parallel pair of 6 ohm and 3 ohm, find the total current. (4) A 9 V source with a 1 ohm and a 2 ohm resistor in series, find the power in the 2 ohm resistor. (5) A 20 V source with a 5 ohm and a 15 ohm resistor in series, find the voltage across the 15 ohm resistor. After finishing, check each answer and mark any that are wrong. If any are wrong, explain the selection rule you missed and re-solve that circuit, then solve one fresh changed circuit of the same type.",
            "completionCriterion": "All five circuits solved with a correct method choice, a valid selection reason, and a correct solution, with no assistance; any wrong item reworked with the missed rule explained and a fresh changed circuit solved correctly.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 90
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "targeted_teaching"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has been taught series, parallel, and series-parallel resistor circuit methods and Ohm's law, since the self-report claims mastery of circuit methods.",
            "The reported 4/5 failure is accurate and refers to changed circuits, not identical practice items."
          ],
          "tradeOffs": [
            "No preparatory lessons are booked before the diagnostic; the diagnostic itself determines what to teach, avoiding wasted time on already-known material.",
            "Remediation is folded into targeted_teaching and is contingent on the diagnostic result rather than a fixed number of practice sets."
          ],
          "unresolvedUncertainty": [
            "The exact methods the learner was taught is not supplied; if a diagnostic circuit requires an untaught method, the learner is instructed to say so rather than guess.",
            "Whether the 4/5 failure was due to method selection, calculation, or both is unknown until the diagnostic is done."
          ],
          "stoppingConditions": [
            "Stop when the independent check is passed with correct method choice, valid reason, and correct solution on all five changed circuits without assistance.",
            "If the independent check still fails, stop and record the unresolved gap honestly rather than certifying mastery."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The self-reported mastery is not credited because the reported 4/5 failure on changed circuits directly contradicts it. The plan spends the first activity locating the actual selection failures rather than assuming a beginner level, then teaches only the rules those failures reveal, and ends with an unaided changed-circuit check. This keeps the work proportionate: no blanket re-teaching, no fixed practice quota, and remediation is triggered by the diagnostic result. The honest risk is that the diagnostic may reveal a deeper gap than method selection; if so, the unresolved uncertainty is recorded rather than papered over."
}

